def clear_simulated_campaigns(apps, schema_editor):
    """Before real sending existed, "dispatch" stored made-up figures (96%
    delivered, 74% read) and up to 10 "delivered" sample messages per
    campaign without sending anything. Put those campaigns back to draft
    with no figures, and mark the sample messages as never sent."""
    BroadcastCampaign = apps.get_model("communications", "BroadcastCampaign")
    Message = apps.get_model("communications", "Message")
    note = "Never actually sent: the old campaign screen only simulated sending. Send it again to reach people."
    BroadcastCampaign.objects.filter(status="completed").update(
        status="draft", total_recipients=0, sent_count=0, delivered_count=0, read_count=0, failed_count=0, error=note)
    Message.objects.filter(provider_message_id__startswith="bcast_", direction="outbound").update(
        status="failed", error="Never sent (old campaign simulator).")


